# - - - Dec 4th experiments
dim = 80
data = [[(1, 50), (0.7071, 50), (0.49999040999999994, 50), (0.35354321891099993, 50), (0.24999041009196804, 50), (0.1767682189760306, 50), (0.12499280763795123, 50), (0.08838241428079531, 46), (0.06249520513795036, 32), (0.04419035955304469, 25)], [(1, 50), (0.7071, 50), (0.49999040999999994, 50), (0.35354321891099993, 50), (0.24999041009196804, 50), (0.1767682189760306, 50), (0.12499280763795123, 50), (0.08838241428079531, 48), (0.06249520513795036, 39), (0.04419035955304469, 24)], [(1, 50), (0.7071, 50), (0.49999040999999994, 50), (0.35354321891099993, 50), (0.24999041009196804, 50), (0.1767682189760306, 50), (0.12499280763795123, 50), (0.08838241428079531, 48), (0.06249520513795036, 33), (0.04419035955304469, 29)], [(1, 50), (0.7071, 50), (0.49999040999999994, 50), (0.35354321891099993, 50), (0.24999041009196804, 50), (0.1767682189760306, 50), (0.12499280763795123, 50), (0.08838241428079531, 45), (0.06249520513795036, 39), (0.04419035955304469, 30)], [(1, 50), (0.7071, 50), (0.49999040999999994, 50), (0.35354321891099993, 50), (0.24999041009196804, 50), (0.1767682189760306, 50), (0.12499280763795123, 50), (0.08838241428079531, 45), (0.06249520513795036, 38), (0.04419035955304469, 26)]]


N = len(data)
print(N)
print(data[0])
Nexperiments = 50 #200.

average = [0]*len(data[0])
factors = [0]*len(data[0])
for i in range(len(data)):
    for j, el in enumerate(data[i]):
        average[j]+=el[1]

for i, el in enumerate(data[0]):
    factors[i] = el[0]
    average[i] = (average[i]/N)/Nexperiments

print(factors)
assert(len(factors)==len(average))


db_sizes = {60: 17919, 70: 75511, 75: 155008, 80: 318200}
db_size = db_sizes[dim]
alpha = db_size**(1/dim)
#TODO: change sqrt(4./3) to the proper base of db.size() used in the experiments
nrand_, _ = batchCVPP_cost(dim,100,alpha,1) #100 can be any constant >1
# print((1./nrand_)**dim)
# print(f"alpha: {alpha} vs sqrt(4/3): {math.sqrt(4/3.)}")

theory = [0]*len(data[0])
dbs = []
for i, el in enumerate(factors):
    # prob, _ = batchCVPP_cost(dim,math.log((1./nrand_)**dim,2),math.sqrt(4./3)*(el)**(1./dim),1)
    prob, _ = batchCVPP_cost(dim,math.log((1./nrand_)**dim,2),alpha*(el)**(1./dim),1.)
    theory[i] = prob
    dbs.append( el )
print("Theory:")
print(theory)
print(f"Practise:")
print(average)


with open('dbsize.csv', "w") as f:
   f.write('factor,succ \n')
   for i in range(len(factors)):
       f.write(str(factors[i])+", "+str(average[i])+'\n')

fig, ax = plt.subplots( figsize=(7.5, 6), layout='constrained' )
xaxis = [ log(tmp,2) for tmp in dbs ]
yaxis_th = theory
yaxis_pr = average
ax.plot( xaxis, yaxis_th, label="Theory" )
ax.plot( xaxis, yaxis_pr, label="Practise" )
ax.set_xlabel('log_2 shrinking factor')
ax.set_ylabel('Success rate')
plt.title("Database size vs. succ. proba")
ax.legend()
plt.savefig(f'succrate_{dim}.png')
print(f'saved at succrate_{dim}.png')
